create procedure [dbo].[ETL_Fact_InvoiceLink]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'Load: [dw].[fact_InvoiceLink]'
			,@Description = ''

	IF @TranCount = 0 begin tran		
		truncate table [dw].[fact_InvoiceLink]
		;with DocuementData as
		(
			select 
				ff.SA_SourceSystemID
				,ff.PageNumber
				,ff.DocumentFileId
				,d.DocumentId
				,d.DocumentType
				,ff.FileName
			from 
				[INSIKT_KUND_SA].[visma].[VWDocumentFile] ff 
					inner join [INSIKT_KUND_SA].[visma].[VWDocument] d on
						ff.DocumentID = d.DocumentId
						AND ff.SA_SourceSystemID = d.SA_SourceSystemID
			where 
				ff.DocumentID = d.DocumentId
				and
				(
					(
						d.DocumentType = 3
					)
					or
					(
						d.DocumentType = 5
						and parsename(ff.FileName, 1) = 'xml'
					)
								
				)
		)
		INSERT INTO [dw].[fact_InvoiceLink]
		(
			[SA_SourceSystemID]
			,[InvoiceDocumentID]
			,[InvoiceLinkConfigurationID]
			,[InvoiceLinkUrl]
		)
		SELECT
			SA_SourceSystemID = d.SA_SourceSystemID
			,InvoiceDocumentID = d.DocumentID
			,InvoiceLinkConfigurationId = 
				case 
					when d.DocumentType = 3 then
						2 -- InternalDisplayWithCopyAndRename: TIF
					when d.DocumentType = 5 then
						4 -- XML, XSLT
					else
						null -- ???
				end
			,[InvoiceLinkUrl] = '?NoOfPages=' + cast(COUNT(*)	as varchar(12)) +
				(
					select 
						'&Page' 
							+ cast(row_number() over (order by ff.PageNumber, ff.DocumentFileId) as varchar(12))
							+ '='
							+ LEFT(d.DocumentId, 1) + RIGHT(d.DocumentId, 1) 
							+ '%5c'
							+ ff.FileName
					from 
						DocuementData ff 
					where 
						ff.DocumentID = d.DocumentId						
					order by
						ff.PageNumber, ff.DocumentFileId
					for xml path(''), type
				).value('.','varchar(max)')
				
		from 
			DocuementData d				
			
		group by
			d.DocumentID
			,d.DocumentType
			,d.SA_SourceSystemID
			
	if @TranCount = 0 commit tran

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

GO
